import requests

url_saml = "https://api17preview.sapsf.com/oauth/idp"

payload_saml='client_id=OTQxY2JlNmFlZjk4ZDI1YjI4OTIyZjQ3NmYzMw&user_id=AgenticAI&token_url=https%3A%2F%2Fapi17preview.sapsf.com%2Fouth%2Ftoken&private_'
headers_saml = {
  'Content-Type': 'application/x-www-form-urlencoded'
}

response_saml = requests.request("POST", url_saml, headers=headers_saml, data=payload_saml)

print(response_saml.text)

url_token = "https://api17preview.sapsf.com/oauth/token"

payload_token='company_id=ontariopowT3&client_id=OTQxY2JlNmFlZjk4ZDI1YjI4OTIyZjQ3NmYzMw&grant_type=urn:ietf:params:oauth:grant-type:saml2-bearer&assertion='+response_saml.text
headers_token = {
  'Content-Type': 'application/x-www-form-urlencoded'
}

response_token = requests.request("POST", url_token, headers=headers_token, data=payload_token)
print('Token')
print(response_token.text)
